sp_widget.client_script:
api.controller = function() {

    var c = this;



    /* ======================================================
       INITIAL FILTER STATE
    ====================================================== */

    c.searchText = '';

    c.typeFilter =
        'all';

    c.categoryFilter =
        'all';



    /* ======================================================
       LOST / FOUND FILTER
    ====================================================== */

    c.setTypeFilter = function(type) {

        c.typeFilter =
            type;

    };



    /* ======================================================
       CATEGORY FILTER
    ====================================================== */

    c.setCategoryFilter = function(category) {

        c.categoryFilter =
            category;

    };



    /* ======================================================
       CLEAR SEARCH
    ====================================================== */

    c.clearSearch = function() {

        c.searchText =
            '';

    };



    /* ======================================================
       RESET EVERYTHING
    ====================================================== */

    c.resetFilters = function() {

        c.searchText =
            '';

        c.typeFilter =
            'all';

        c.categoryFilter =
            'all';

    };



    /* ======================================================
       FILTER REAL ITEMS
    ====================================================== */

    c.filteredItems = function() {

        var items =
            c.data.items || [];


        var search =
            (
                c.searchText ||
                ''
            )
            .toLowerCase()
            .trim();


        return items.filter(
            function(item) {


                /* ------------------------------------------
                   LOST / FOUND
                ------------------------------------------ */

                if (
                    c.typeFilter !== 'all' &&
                    item.reportType !==
                        c.typeFilter
                ) {

                    return false;

                }



                /* ------------------------------------------
                   CATEGORY
                ------------------------------------------ */

                if (
                    c.categoryFilter !== 'all' &&
                    item.categoryValue !==
                        c.categoryFilter
                ) {

                    return false;

                }



                /* ------------------------------------------
                   SEARCH
                ------------------------------------------ */

                if (search) {

                    var searchable =
                        (
                            (
                                item.publicTitle ||
                                ''
                            )
                            +
                            ' '
                            +
                            (
                                item.category ||
                                ''
                            )
                        )
                        .toLowerCase();


                    if (
                        searchable.indexOf(
                            search
                        ) === -1
                    ) {

                        return false;

                    }

                }



                return true;

            }
        );

    };



    /* ======================================================
       BUILD CATEGORY DROPDOWN FROM REAL RECORDS
    ====================================================== */

    c.getCategories = function() {

        var items =
            c.data.items || [];


        var seen =
            {};


        var categories =
            [];


        items.forEach(
            function(item) {


                if (
                    item.categoryValue &&
                    !seen[
                        item.categoryValue
                    ]
                ) {

                    seen[
                        item.categoryValue
                    ] =
                        true;


                    categories.push({

                        value:
                            item.categoryValue,

                        label:
                            item.category

                    });

                }

            }
        );


        /*
         * Sort alphabetically so the
         * dropdown stays clean.
         */

        categories.sort(
            function(a, b) {

                return a.label.localeCompare(
                    b.label
                );

            }
        );


        return categories;

    };

};

sp_widget.css:
/* ============================================================
   CAMPUSMATCH EXPLORE
   WEBSITE + NOW MOBILE APP
============================================================ */

.cm-explore {
  position: relative;

  /*
     FULL-BLEED FIX
     Escapes ServiceNow's parent container padding.
  */
  width: 100vw;
  max-width: 100vw;

  margin:
    0
    calc(50% - 50vw);

  min-height: 100vh;
  min-height: 100svh;

  padding:
    58px
    20px
    90px;

  background: #FBF8EF;

  color: #102E34;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  box-sizing: border-box;

  overflow-x: hidden;
}


/* ============================================================
   SAFE BOX SIZING
============================================================ */

.cm-explore,
.cm-explore *,
.cm-explore *::before,
.cm-explore *::after {
  box-sizing: border-box;
}


/* ============================================================
   INNER CONTENT CONTAINER
============================================================ */

.cm-explore-container {
  width: 100%;

  max-width: 1240px;

  margin:
    0
    auto;
}


/* ============================================================
   PAGE HEADER
============================================================ */

.cm-explore-header {
  max-width: 680px;

  margin:
    0
    auto
    38px;

  text-align: center;
}


.cm-explore-eyebrow {
  display: inline-flex;
  align-items: center;

  padding:
    8px
    16px;

  margin-bottom: 17px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 13px;

  font-weight: 700;
}


.cm-explore-header h1 {
  margin:
    0
    0
    10px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 42px;

  font-weight: 700;

  line-height: 1.12;

  letter-spacing: -1.2px;
}


.cm-explore-header p {
  margin: 0;

  color: #506267;

  font-size: 16px;

  line-height: 1.55;
}


/* ============================================================
   SEARCH
============================================================ */

.cm-search {
  width: 100%;

  max-width: 820px;

  height: 58px;

  margin:
    0
    auto
    22px;

  padding:
    0
    19px;

  display: flex;

  align-items: center;

  gap: 12px;

  border: 1.5px solid #D2DED8;

  border-radius: 999px;

  background: #FFFFFF;

  box-shadow:
    0 7px 22px rgba(16,78,69,.06);
}


.cm-search > svg {
  width: 21px;

  height: 21px;

  flex-shrink: 0;

  color: #758589;
}


.cm-search input {
  width: 100%;

  height: 100%;

  min-width: 0;

  padding: 0;

  border: 0;

  outline: 0;

  background: transparent;

  color: #102E34;

  font-family: inherit;

  font-size: 15px;
}


.cm-search input::placeholder {
  color: #899699;
}


.cm-clear-search {
  width: 32px;

  height: 32px;

  padding: 0;

  flex-shrink: 0;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 0;

  border-radius: 50%;

  background: #EDF5E9;

  color: #15564B;

  font-size: 21px;

  line-height: 1;

  cursor: pointer;
}


/* ============================================================
   FILTERS
============================================================ */

.cm-filter-bar {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 16px;

  margin-bottom: 36px;
}


.cm-filter-chips {
  display: flex;

  flex-wrap: wrap;

  gap: 9px;
}


.cm-filter-chips button {
  padding:
    10px
    20px;

  border: 1.5px solid #D2DED8;

  border-radius: 999px;

  background: #FFFFFF;

  color: #102E34;

  font-family: inherit;

  font-size: 13px;

  font-weight: 700;

  cursor: pointer;

  transition:
    background .2s ease,
    border .2s ease,
    color .2s ease;
}


.cm-filter-chips button:hover {
  border-color: #249D78;
}


.cm-filter-chips button.active {
  border-color: #104E45;

  background: #104E45;

  color: #FFFFFF;
}


.cm-category-filter {
  min-width: 175px;

  padding:
    10px
    15px;

  border: 1.5px solid #D2DED8;

  border-radius: 13px;

  outline: none;

  background: #FFFFFF;

  color: #102E34;

  font-family: inherit;

  font-size: 13px;

  font-weight: 600;
}


/* ============================================================
   RESULT COUNT
============================================================ */

.cm-results-head {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 16px;

  margin-bottom: 18px;

  color: #677A7E;

  font-size: 13px;
}


.cm-results-head strong {
  margin-right: 4px;

  color: #104E45;

  font-size: 16px;
}


.cm-reset-filter {
  padding: 0;

  border: 0;

  background: transparent;

  color: #168C70;

  font-family: inherit;

  font-size: 12px;

  font-weight: 700;

  cursor: pointer;
}


/* ============================================================
   ITEM GRID
============================================================ */

.cm-item-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 24px;
}


/* ============================================================
   CARD
============================================================ */

.cm-item-card {
  min-width: 0;

  overflow: hidden;

  border: 1px solid #D2DED8;

  border-radius: 23px;

  background: #FFFFFF;

  box-shadow:
    0 5px 18px rgba(16,78,69,.06);

  transition:
    transform .22s ease,
    box-shadow .22s ease;
}


.cm-item-card:hover {
  transform: translateY(-4px);

  box-shadow:
    0 13px 30px rgba(16,78,69,.11);
}


/* ============================================================
   GENERIC MEDIA
============================================================ */

.cm-item-media {
  position: relative;

  height: 190px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  overflow: hidden;

  background:
    linear-gradient(
      145deg,
      #EDF5E9,
      #E3F0E5
    );
}


.cm-item-media.lost {
  background:
    linear-gradient(
      145deg,
      #F9EEE8,
      #F7E7E2
    );
}


/* ============================================================
   STEP 10
   STAFF ITEM IMAGE
============================================================ */

.cm-item-image {
  position: absolute;

  inset: 0;

  width: 100%;

  height: 100%;

  display: block;

  object-fit: cover;

  object-position: center;

  z-index: 1;
}


.cm-category-icon {
  position: relative;

  width: 74px;

  height: 74px;

  display: flex;

  align-items: center;

  justify-content: center;

  margin-bottom: 9px;

  border-radius: 23px;

  background: rgba(255,255,255,.72);

  color: #15564B;

  z-index: 2;
}


.cm-item-media.lost .cm-category-icon {
  color: #A65A41;
}


.cm-category-icon svg {
  width: 39px;

  height: 39px;
}


.cm-category-caption {
  position: relative;

  color: #506267;

  font-size: 12px;

  font-weight: 600;

  z-index: 2;
}


/* ============================================================
   TYPE BADGE
============================================================ */

.cm-type-badge {
  position: absolute;

  top: 13px;

  left: 13px;

  padding:
    6px
    12px;

  border-radius: 999px;

  font-size: 11px;

  font-weight: 800;

  z-index: 3;
}


.cm-lost-badge {
  background: #FFFFFF;

  color: #A54A34;
}


.cm-found-badge {
  background: #FFFFFF;

  color: #15564B;
}


/* ============================================================
   CARD BODY
============================================================ */

.cm-item-body {
  padding:
    20px
    21px
    19px;
}


.cm-item-body h3 {
  min-height: 46px;

  margin:
    0
    0
    11px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 17px;

  line-height: 1.35;

  font-weight: 700;
}


/* ============================================================
   ITEM META
   DATE/TIME + CATEGORY
   CHANGED TO BLACK
============================================================ */

.cm-item-meta {
  display: flex;

  flex-direction: column;

  gap: 7px;

  color: #000000;

  font-size: 12px;
}


.cm-item-meta span {
  display: flex;

  align-items: center;

  gap: 6px;
}


.cm-item-meta svg {
  width: 14px;

  height: 14px;

  flex-shrink: 0;
}


/* ============================================================
   ADMIN INFORMATION
============================================================ */

.cm-admin-details {
  margin-top: 15px;

  padding:
    12px
    13px;

  border-radius: 13px;

  background: #F4F8F2;
}


.cm-admin-row {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 12px;

  padding:
    4px
    0;

  font-size: 11px;
}


/* LOCATION + STATUS HEADINGS CHANGED TO BLACK */

.cm-admin-row span {
  color: #000000;
}


/* LOCATION + STATUS VALUES REMAIN GREEN */

.cm-admin-row strong {
  color: #104E45;

  text-align: right;

  word-break: break-word;
}


/* ============================================================
   CARD FOOTER
============================================================ */

.cm-item-footer {
  display: flex;

  justify-content: flex-end;

  margin-top: 18px;

  padding-top: 14px;

  border-top: 1px solid #EDF2EE;
}


.cm-view-link {
  display: inline-flex;

  align-items: center;

  gap: 7px;

  color: #104E45 !important;

  font-size: 13px;

  font-weight: 800;

  text-decoration: none !important;
}


.cm-view-link span {
  font-size: 18px;

  transition:
    transform .2s ease;
}


.cm-view-link:hover span {
  transform: translateX(4px);
}


/* ============================================================
   EMPTY STATE
============================================================ */

.cm-empty-state {
  width: 100%;

  max-width: 460px;

  margin:
    70px
    auto;

  padding:
    42px
    25px;

  text-align: center;
}


.cm-empty-icon {
  width: 72px;

  height: 72px;

  margin:
    0
    auto
    17px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 23px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-empty-icon svg {
  width: 32px;

  height: 32px;
}


.cm-empty-state h3 {
  margin:
    0
    0
    7px;

  color: #104E45;
}


.cm-empty-state p {
  margin:
    0
    0
    18px;

  color: #718185;
}


.cm-empty-reset {
  padding:
    10px
    18px;

  border: 1.5px solid #D2DED8;

  border-radius: 999px;

  background: #FFFFFF;

  color: #104E45;

  font-family: inherit;

  font-weight: 700;

  cursor: pointer;
}


/* ============================================================
   BOTTOM CTA
============================================================ */

.cm-explore-cta {
  margin-top: 60px;

  padding:
    28px
    32px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 30px;

  border-radius: 24px;

  background: #104E45;

  color: #FFFFFF;
}


.cm-explore-cta h2 {
  margin:
    0
    0
    6px;

  color: #FFFFFF;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 21px;

  line-height: 1.3;
}


.cm-explore-cta p {
  margin: 0;

  color: rgba(255,255,255,.72);

  font-size: 13px;

  line-height: 1.5;
}


.cm-cta-buttons {
  display: flex;

  gap: 10px;

  flex-shrink: 0;
}


.cm-cta-buttons a {
  padding:
    11px
    18px;

  border-radius: 999px;

  font-size: 12px;

  font-weight: 800;

  text-decoration: none !important;

  white-space: nowrap;
}


.cm-cta-primary {
  background: #FFFFFF;

  color: #104E45 !important;
}


.cm-cta-secondary {
  border: 1px solid rgba(255,255,255,.5);

  color: #FFFFFF !important;
}


/* ============================================================
   TABLET
   WEBSITE TABLET + NOW MOBILE LARGE WIDTH
============================================================ */

@media (max-width: 950px) {

  .cm-explore {
    padding:
      50px
      24px
      80px;
  }


  .cm-item-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


/* ============================================================
   MOBILE
   WEBSITE MOBILE + NOW MOBILE APP
============================================================ */

@media (max-width: 650px) {

  .cm-explore {
    min-height: 100svh;

    padding:
      38px
      16px
      70px;
  }


  .cm-explore-header {
    margin-bottom: 28px;
  }


  .cm-explore-eyebrow {
    padding:
      7px
      14px;

    font-size: 12px;
  }


  .cm-explore-header h1 {
    font-size: 31px;

    letter-spacing: -0.8px;
  }


  .cm-explore-header p {
    font-size: 14px;
  }


  .cm-search {
    height: 52px;

    padding:
      0
      16px;
  }


  .cm-search input {
    font-size: 14px;
  }


  .cm-filter-bar {
    align-items: stretch;

    flex-direction: column;

    gap: 13px;

    margin-bottom: 30px;
  }


  .cm-filter-chips {
    display: grid;

    grid-template-columns:
      repeat(3, minmax(0, 1fr));

    width: 100%;
  }


  .cm-filter-chips button {
    width: 100%;

    padding:
      10px
      8px;
  }


  .cm-category-filter {
    width: 100%;

    min-width: 0;
  }


  .cm-item-grid {
    grid-template-columns: 1fr;

    gap: 18px;
  }


  .cm-item-media {
    height: 175px;
  }


  .cm-item-body h3 {
    min-height: auto;
  }


  .cm-explore-cta {
    align-items: stretch;

    flex-direction: column;

    gap: 20px;

    margin-top: 45px;

    padding:
      24px
      21px;
  }


  .cm-cta-buttons {
    width: 100%;
  }


  .cm-cta-buttons a {
    flex: 1;

    text-align: center;
  }

}


/* ============================================================
   SMALL PHONE / NOW MOBILE
============================================================ */

@media (max-width: 480px) {

  .cm-explore {
    padding:
      34px
      14px
      60px;
  }


  .cm-explore-header {
    margin-bottom: 24px;
  }


  .cm-explore-header h1 {
    font-size: 28px;
  }


  .cm-explore-header p {
    font-size: 13px;
  }


  .cm-search {
    height: 50px;

    margin-bottom: 18px;
  }


  .cm-filter-bar {
    margin-bottom: 26px;
  }


  .cm-filter-chips {
    gap: 7px;
  }


  .cm-filter-chips button {
    font-size: 12px;
  }


  .cm-results-head {
    margin-bottom: 14px;
  }


  .cm-item-card {
    border-radius: 20px;
  }


  .cm-item-media {
    height: 160px;
  }


  .cm-category-icon {
    width: 66px;

    height: 66px;

    border-radius: 20px;
  }


  .cm-category-icon svg {
    width: 34px;

    height: 34px;
  }


  .cm-item-body {
    padding:
      18px
      17px;
  }


  .cm-explore-cta {
    border-radius: 20px;
  }

}


/* ============================================================
   VERY SMALL PHONE
============================================================ */

@media (max-width: 390px) {

  .cm-explore {
    padding:
      30px
      12px
      55px;
  }


  .cm-explore-header h1 {
    font-size: 26px;
  }


  .cm-explore-header p {
    font-size: 12px;
  }


  .cm-search {
    height: 48px;

    padding:
      0
      13px;
  }


  .cm-filter-chips button {
    padding:
      9px
      5px;

    font-size: 11px;
  }


  .cm-item-media {
    height: 150px;
  }


  .cm-cta-buttons {
    flex-direction: column;
  }


  .cm-cta-buttons a {
    width: 100%;
  }

}

sp_widget.script:
(function() {

    /* ======================================================
       TABLE
    ====================================================== */

    var ITEM_TABLE =
        'x_snc_campusmatch_campusmatch_item';


    /*
     * CampusMatch uploaded images are converted into
     * ServiceNow user_image attachments using this table name.
     */

    var ITEM_IMAGE_ATTACHMENT_TABLE =
        'ZZ_YY' + ITEM_TABLE;



    /* ======================================================
       FIELD NAMES
    ====================================================== */

    var F_TYPE =
        'report_type';

    var F_PUBLIC_TITLE =
        'public_title';

    var F_CATEGORY =
        'category';

    var F_LOCATION =
        'location_zone';

    var F_REPORTED =
        'reported_date_time';

    var F_STATUS =
        'status';



    /* ======================================================
       OUTPUT
    ====================================================== */

    data.items = [];



    /* ======================================================
       TASK 14 - CENTRALIZED STAFF ACCESS
    ====================================================== */

    var access =
        new CampusMatchAccess();


    data.isStaff =
        access.isStaff();


    /*
     * Temporary compatibility in case the existing
     * Explore Items HTML still uses data.isAdmin.
     */

    data.isAdmin =
        data.isStaff;



    /* ======================================================
       STEP 8
       GET ACTUAL ITEM IMAGE FOR STAFF ONLY
    ====================================================== */

    function getItemImageUrl(
        itemSysId
    ) {

        if (
            !itemSysId
        ) {

            return '';

        }


        var imageAttachment =
            new GlideRecord(
                'sys_attachment'
            );


        imageAttachment.addQuery(
            'table_sys_id',
            itemSysId
        );


        imageAttachment.addQuery(
            'table_name',
            ITEM_IMAGE_ATTACHMENT_TABLE
        );


        imageAttachment.addQuery(
            'file_name',
            'image'
        );


        /*
         * If more than one converted image exists,
         * use the newest one.
         */

        imageAttachment.orderByDesc(
            'sys_created_on'
        );


        imageAttachment.setLimit(
            1
        );


        imageAttachment.query();


        if (
            imageAttachment.next()
        ) {

            return (
                '/sys_attachment.do?sys_id=' +
                imageAttachment.getUniqueValue() +
                '&view=true'
            );

        }


        return '';

    }



    /* ======================================================
       QUERY REAL CAMPUSMATCH ITEMS
    ====================================================== */

    var item =
        new GlideRecord(
            ITEM_TABLE
        );


    /*
     * Show newest reports first.
     */

    item.orderByDesc(
        'sys_created_on'
    );


    /*
     * Safety limit for Explore.
     */

    item.setLimit(
        100
    );


    item.query();



    /* ======================================================
       BUILD PRIVACY-SAFE ITEM OBJECTS
    ====================================================== */

    while (
        item.next()
    ) {


        /* ------------------------------------------
           REPORT TYPE
        ------------------------------------------ */

        var rawType =
            item.getValue(
                F_TYPE
            ) || '';


        var reportType =
            rawType
                .toString()
                .toLowerCase()
                .trim();



        /*
         * Ignore malformed / unexpected records.
         */

        if (
            reportType !== 'lost' &&
            reportType !== 'found'
        ) {

            continue;

        }



        /* ------------------------------------------
           PUBLIC TITLE
        ------------------------------------------ */

        var publicTitle =
            item.getDisplayValue(
                F_PUBLIC_TITLE
            ) || '';


        /*
         * PRIVACY:
         *
         * NEVER fall back to the raw Title field.
         *
         * If Public Title has not yet been generated,
         * use a generic safe fallback.
         */

        if (
            !publicTitle
        ) {

            if (
                reportType === 'found'
            ) {

                publicTitle =
                    'Found Item';

            }
            else {

                publicTitle =
                    'Lost Item';

            }

        }



        /* ------------------------------------------
           CATEGORY
        ------------------------------------------ */

        var categoryValue =
            item.getValue(
                F_CATEGORY
            ) || 'other';


        categoryValue =
            categoryValue
                .toString()
                .toLowerCase()
                .trim();


        var categoryDisplay =
            item.getDisplayValue(
                F_CATEGORY
            ) || 'Other';



        /* ==================================================
           STUDENT-SAFE PUBLIC RECORD

           IMPORTANT:
           Do NOT add:
           - raw title
           - description
           - reporter
           - brand
           - color
           - private verification details
           - AI attribute text
           - location_x
           - location_y
           - uploaded image
        ================================================== */

        var record = {

            sys_id:
                item.getUniqueValue(),

            reportType:
                reportType,

            reportTypeLabel:
                reportType === 'found'
                    ? 'Found'
                    : 'Lost',

            publicTitle:
                publicTitle,

            category:
                categoryDisplay,

            categoryValue:
                categoryValue,

            reported:
                item.getDisplayValue(
                    F_REPORTED
                ) || '—'

        };



        /* ==================================================
           STAFF-ONLY OPERATIONAL INFORMATION

           STEP 8:
           Actual uploaded image is exposed ONLY here.
           Students never receive record.imageUrl.
        ================================================== */

        if (
            data.isStaff
        ) {

            record.location =
                item.getDisplayValue(
                    F_LOCATION
                ) || '—';


            record.status =
                item.getDisplayValue(
                    F_STATUS
                ) || '—';


            /* =============================================
               STAFF-ONLY ACTUAL ITEM IMAGE
            ============================================= */

            record.imageUrl =
                getItemImageUrl(
                    item.getUniqueValue()
                );

        }



        /* ==================================================
           ADD TO OUTPUT
        ================================================== */

        data.items.push(
            record
        );

    }

})();
